//! Correctness golden against the official ISO 532-1:2017 Annex A C program
//! (decision D4 as revised on 2026-11-04 / phase plan 0.4.0 D-D, D-G): the
//! official `ISO_532-1.c` with only USL[12][4] changed 0.22f -> 0.24f,
//! generated by `tools/gen_golden_c.py` into `data/golden-c/` (gitignored;
//! hashes in `tools/golden-c.sha256`).
//!
//! Gates, three tiers:
//!
//! * C-01 tail points (last output point of Annex B signals 18/23/24/25):
//!   total and specific loudness within `TAIL_TOL` = 1e-10 sone, the
//!   acceptance criterion of the 0.4.0 phase.
//! * Whole series, total loudness: `SERIES_TOTAL_TOL` = 1e-4 sone. The
//!   official C moves every band edge by its `_ZUP += .0001f` epsilon and uses
//!   float32 table/constant literals, so no binary64 implementation agrees
//!   with it to 1e-10 over a whole series (measured maximum 2.712e-5 sone,
//!   annexb_sig5).
//! * Whole series, specific loudness: `SERIES_SPEC_TOL` = 3e-4 sone/Bark, the
//!   measured maximum after F-07 (2.100e-4, sine_250_80) rounded up to one
//!   significant digit; the same epsilon bounds it by 1e-4 Bark x USL <= 13
//!   x 1e-4. Before F-07 (Rust wrote the slope extrapolated past its end in
//!   the cell where a slope meets the core loudness) the maximum was 4.377e-2.
//!
//! Measured maxima at the Round 2 commit (Rust vs C(0.24f), default AVX2
//! dispatch, Windows):
//!
//! | signal           | zwtv total | zwtv specific | zwst total | zwst specific |
//! |------------------|-----------:|--------------:|-----------:|--------------:|
//! | sine_1k_60       |  1.471e-7  |   6.184e-5    |  1.415e-7  |   6.183e-5    |
//! | sine_250_80      |  2.022e-5  |   2.100e-4    |  4.650e-6  |   1.500e-4    |
//! | sine_4k_60       |  4.987e-8  |   8.214e-5    |  3.802e-8  |   8.214e-5    |
//! | white_60         |  1.915e-6  |   6.235e-5    |  3.688e-7  |   4.220e-5    |
//! | pulse_1k_70      |  1.465e-7  |   1.097e-4    |  6.723e-8  |   4.189e-5    |
//! | step_60_80       |  1.645e-6  |   1.297e-4    |  2.371e-7  |   1.297e-4    |
//! | annexb_sig3      |  1.472e-7  |   6.184e-5    |  1.448e-7  |   6.183e-5    |
//! | annexb_sig5      |  2.712e-5  |   6.235e-5    |  1.530e-5  |   4.206e-5    |
//! | annexb_sig10     |  9.795e-8  |   1.097e-4    |  7.257e-8  |   4.189e-5    |
//! | annexb_c01_sig18 |  6.614e-6  |   9.397e-5    |     -      |      -        |
//! | annexb_c01_sig23 |  3.248e-7  |   8.249e-5    |     -      |      -        |
//! | annexb_c01_sig24 |  1.753e-6  |   6.217e-5    |     -      |      -        |
//! | annexb_c01_sig25 |  7.781e-7  |   8.249e-5    |     -      |      -        |
//!
//! `golden_c_data_is_complete_and_on_the_output_grid` checks every file
//! fail-closed and prints these maxima (also against the unmodified C).
//! Missing or malformed golden data is a hard failure, never a skip.

mod common;
use common::read_bin_path;
use iso532::core::calc_slopes::calc_slopes;
use iso532::core::main_loudness::main_loudness;
use iso532::{loudness_zwtv, zwtv_out_frames, FieldType, LoudnessTimeVarying};
use std::path::PathBuf;

/// C-01 tail points, total and specific loudness (sone, sone/Bark).
const TAIL_TOL: f64 = 1e-10;
/// Whole series, total loudness (sone).
const SERIES_TOTAL_TOL: f64 = 1e-4;
/// Whole series, specific loudness (sone/Bark).
const SERIES_SPEC_TOL: f64 = 3e-4;

/// The nine signals of `tools/gen_golden.py`.
const SIGNALS: [&str; 9] = [
    "sine_1k_60",
    "sine_250_80",
    "sine_4k_60",
    "white_60",
    "pulse_1k_70",
    "step_60_80",
    "annexb_sig3",
    "annexb_sig5",
    "annexb_sig10",
];

/// Annex B signals 18/23/24/25 (C-01 tail points).
const C01: [&str; 4] = [
    "annexb_c01_sig18",
    "annexb_c01_sig23",
    "annexb_c01_sig24",
    "annexb_c01_sig25",
];

fn golden_c_path(name: &str, file: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .join("data/golden-c")
        .join(name)
        .join(file)
}

/// Fail-closed reader: missing file, partial f64 words, empty data or
/// non-finite values all panic.
fn read_c(name: &str, file: &str) -> Vec<f64> {
    let path = golden_c_path(name, file);
    assert!(
        path.is_file(),
        "missing C golden {path:?}: run tools/gen_golden_c.py (see its docstring)"
    );
    let v = read_bin_path(&path);
    assert!(!v.is_empty(), "C golden {path:?} is empty");
    if let Some(i) = v.iter().position(|x| !x.is_finite()) {
        panic!("C golden {path:?}[{i}] is not finite: {}", v[i]);
    }
    v
}

/// Max |got - want| with fail-closed length and finiteness checks.
fn max_abs_diff(got: &[f64], want: &[f64], ctx: &str) -> (f64, usize) {
    assert!(!want.is_empty(), "{ctx}: empty reference");
    assert_eq!(got.len(), want.len(), "{ctx}: length mismatch");
    let mut worst = (0.0, 0);
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(g.is_finite(), "{ctx}[{i}]: result not finite: {g}");
        let d = (g - w).abs();
        if d > worst.0 {
            worst = (d, i);
        }
    }
    worst
}

struct Zwtv {
    rust: LoudnessTimeVarying,
    total: Vec<f64>,
    specific: Vec<f64>,
    total_official: Vec<f64>,
    specific_official: Vec<f64>,
}

fn zwtv_case(name: &str) -> Zwtv {
    let sig = read_c(name, "sig.bin");
    let rust = loudness_zwtv(&sig, 48000.0, FieldType::Free).unwrap();
    let n = zwtv_out_frames(sig.len());
    let total = read_c(name, "zwtv_total.bin");
    let specific = read_c(name, "zwtv_specific.bin");
    let time = read_c(name, "zwtv_time.bin");
    let total_official = read_c(name, "zwtv_total_official.bin");
    let specific_official = read_c(name, "zwtv_specific_official.bin");
    assert_eq!(rust.n.len(), n, "{name}: Rust output grid");
    for (file, len, want) in [
        ("zwtv_total", total.len(), n),
        ("zwtv_time", time.len(), n),
        ("zwtv_total_official", total_official.len(), n),
        ("zwtv_specific", specific.len(), 240 * n),
        ("zwtv_specific_official", specific_official.len(), 240 * n),
    ] {
        assert_eq!(len, want, "{name}/{file}: length");
    }
    for (j, (a, b)) in rust.time_axis.iter().zip(&time).enumerate() {
        assert_eq!(a.to_bits(), b.to_bits(), "{name}: time[{j}] {a} vs {b}");
    }
    Zwtv {
        rust,
        total,
        specific,
        total_official,
        specific_official,
    }
}

fn zwst_core(name: &str) -> (f64, [f64; 240], f64, Vec<f64>) {
    let levels = read_c(name, "zwst_levels.bin");
    assert_eq!(levels.len(), 28, "{name}: zwst levels");
    let total = read_c(name, "zwst_total.bin");
    assert_eq!(total.len(), 1, "{name}: zwst total");
    let specific = read_c(name, "zwst_specific.bin");
    assert_eq!(specific.len(), 240, "{name}: zwst specific");
    let nm = main_loudness(&levels, FieldType::Free).unwrap();
    let nm: [f64; 21] = nm.as_slice().try_into().unwrap();
    let (n, spec) = calc_slopes(&nm);
    (n, spec, total[0], specific)
}

#[test]
fn c01_tail_points_match_annex_a_c_within_1e_10() {
    for name in C01 {
        let c = zwtv_case(name);
        let n = c.total.len();
        let j = n - 1;
        let d_total = c.rust.n[j] - c.total[j];
        let d_official = c.rust.n[j] - c.total_official[j];
        let tail_rust: Vec<f64> = (0..240).map(|b| c.rust.n_specific[b * n + j]).collect();
        let tail_c: Vec<f64> = (0..240).map(|b| c.specific[b * n + j]).collect();
        let (d_spec, bark) = max_abs_diff(&tail_rust, &tail_c, name);
        eprintln!(
            "{name} point {j}: Rust {:.17e} C(0.24f) {:.17e} diff {d_total:+.3e}; \
             vs unmodified C {d_official:+.3e}; specific max {d_spec:.3e} (bark {bark})",
            c.rust.n[j], c.total[j]
        );
        assert!(
            d_total.abs() <= TAIL_TOL,
            "{name}: tail total |diff| {:e} > {TAIL_TOL:e}",
            d_total.abs()
        );
        assert!(
            d_spec <= TAIL_TOL,
            "{name}: tail specific |diff| {d_spec:e} > {TAIL_TOL:e} at bark {bark}"
        );
    }
}

#[test]
fn golden_c_data_is_complete_and_on_the_output_grid() {
    for name in SIGNALS.iter().chain(&C01) {
        let c = zwtv_case(name);
        let (dt, it) = max_abs_diff(&c.rust.n, &c.total, name);
        let (ds, is) = max_abs_diff(&c.rust.n_specific, &c.specific, name);
        let (dto, _) = max_abs_diff(&c.rust.n, &c.total_official, name);
        let (dso, _) = max_abs_diff(&c.rust.n_specific, &c.specific_official, name);
        let n = c.total.len();
        eprintln!(
            "{name}: zwtv vs C(0.24f) total max {dt:.3e} (point {it}), specific max {ds:.3e} \
             (bark {}, point {}); vs unmodified C total {dto:.3e}, specific {dso:.3e}",
            is / n,
            is % n
        );
        if SIGNALS.contains(name) {
            let (n_rust, spec_rust, n_c, spec_c) = zwst_core(name);
            let (dss, bark) = max_abs_diff(&spec_rust, &spec_c, name);
            eprintln!(
                "{name}: zwst (main_loudness + calc_slopes on the golden levels) total \
                 diff {:.3e}, specific max {dss:.3e} (bark {bark})",
                (n_rust - n_c).abs()
            );
        }
    }
}

#[test]
fn zwtv_whole_series_matches_annex_a_c() {
    for name in SIGNALS.iter().chain(&C01) {
        let c = zwtv_case(name);
        let (dt, it) = max_abs_diff(&c.rust.n, &c.total, name);
        assert!(
            dt <= SERIES_TOTAL_TOL,
            "{name}: total |diff| {dt:e} > {SERIES_TOTAL_TOL:e} at point {it}"
        );
        let (ds, is) = max_abs_diff(&c.rust.n_specific, &c.specific, name);
        assert!(
            ds <= SERIES_SPEC_TOL,
            "{name}: specific |diff| {ds:e} > {SERIES_SPEC_TOL:e} at index {is}"
        );
    }
}

#[test]
fn zwst_matches_annex_a_c() {
    for name in SIGNALS {
        let (n_rust, spec_rust, n_c, spec_c) = zwst_core(name);
        assert!(
            (n_rust - n_c).abs() <= SERIES_TOTAL_TOL,
            "{name}: N {n_rust} vs {n_c}"
        );
        let (ds, bark) = max_abs_diff(&spec_rust, &spec_c, name);
        assert!(
            ds <= SERIES_SPEC_TOL,
            "{name}: specific |diff| {ds:e} > {SERIES_SPEC_TOL:e} at bark {bark}"
        );
    }
}
